<!-- This file is generated by AI. -->

<!--
  目录浏览组件: 每次只打开一层目录 (文件夹 + 文件), 不递归扫描子目录; 支持返回上级、
  在当前目录内搜索、展平当前目录 (递归列文件)。

  长目录**分页渲染**: 一次只挂前 `FILE_TREE_PAGE_SIZE` 行, 滚到接近底部 (或点"加载更多")
  再补一页 —— 磁盘读取很快, 卡的是几千个 DOM 节点与同样多的缩略图请求。

  视图状态 (当前目录/搜索词/展平/已渲染行数/滚动位置) 由调用方经 `viewStateCache` 提供,
  "切到别的侧栏页再切回来"才不会丢掉浏览位置; 缓存刻意是**外部传入的 Map**, 因为组件本身
  会随侧栏切换而卸载。

  ⚠️ 这个组件**刻意不带 `<style>` 块**: 它用的 `.file-tree-*` / `.resource-*` 类名全部来自
  全局 `styles.css`。Svelte 只在"组件自己写了 `<style>`"时才会给模板类名加作用域哈希, 一旦
  加上, 那些全局规则就再也匹配不上 —— 界面会静默失去样式。需要新样式就加到 `styles.css`。
-->

<script lang="ts">
  import type { Snippet } from 'svelte';

  import { compareNames } from '../lib/collate';
  import { fs, type Unwatch } from '../lib/fs';
  import { JSON_EXT, kindFor, type FileKind } from '../lib/fileKind';
  import { relativeDirectoryPath, samePath } from '../lib/paths';
  import { mapLimited } from '../lsp/change-batch';
  import ContextMenu, { type ContextMenuItem } from './ContextMenu.svelte';
  import Icon from './Icon.svelte';

  /** 一次渲染多少行; 滚到接近底部时再补一页 */
  export const FILE_TREE_PAGE_SIZE = 120;

  /** 目录变化后的刷新防抖; 与 `plugin-fs` 的 watch 延迟一致 */
  const WATCH_DEBOUNCE_MS = 160;

  /** 展平模式下同时遍历多少个子目录 (与 `lsp/change-batch.ts` 的存在性复核同一量级) */
  const FLAT_WALK_CONCURRENCY = 16;

  export interface FileNode {
    name: string;
    path: string;
    /** 相对根路径 (正斜杠) */
    rel: string;
    isDirectory: boolean;
    kind: FileKind;
  }

  export interface FileTreeViewState {
    currentRel: string;
    query: string;
    flat: boolean;
    visibleCount: number;
    scrollTop: number;
  }

  export type FileTreeViewStateCache = Map<string, FileTreeViewState>;

  export interface FileTreeRevealRequest {
    id: number;
    path: string;
  }

  /** 长名称中间省略: 保留开头与扩展名后缀。 */
  export function middleEllipsis(text: string, maxLen: number): string {
    if (text.length <= maxLen) return text;
    const dot = text.lastIndexOf('.');
    const hasExt = dot > 0 && dot < text.length - 1;
    const ext = hasExt ? text.slice(dot) : '';
    const stem = hasExt ? text.slice(0, dot) : text;
    const avail = maxLen - ext.length - 3;
    if (avail < 4) return `${text.slice(0, Math.max(1, maxLen - 3))}...`;
    const keepHead = Math.ceil(avail / 2);
    const keepTail = avail - keepHead;
    return `${stem.slice(0, keepHead)}...${stem.slice(stem.length - keepTail)}${ext}`;
  }

  export const KIND_BADGE: Record<FileKind, string> = {
    image: 'IMG',
    audio: '♪',
    video: '▶',
    text: 'TXT',
    scene: 'SCN',
    other: '?',
  };

  export function badgeFor(name: string, kind: FileKind): string {
    const extension = name.slice(name.lastIndexOf('.') + 1).toLowerCase();
    if (JSON_EXT.includes(extension)) return 'JSON';
    if (kind === 'text' && extension) return extension.toUpperCase();
    return KIND_BADGE[kind];
  }

  /**
   * 拼一个跨平台路径。
   *
   * 刻意不用 `lib/paths.ts` 的 `joinPath`: 那个是"给用户看的路径"(统一正斜杠), 而这里要的是
   * **能交给 `plugin-fs` 的真实路径**。Windows 上正斜杠虽然多数场合能用, 但 `watch` 与
   * `readDir` 走的是 Rust 侧, 混用分隔符在少数情况下会被判成不同路径。
   */
  function joinNative(directory: string, child: string): string {
    const separator = directory.includes('\\') ? '\\' : '/';
    return `${directory.replace(/[\\/]+$/, '')}${separator}${child}`;
  }

  /**
   * 取当前目录**之上**的父目录 (用于目录消失时的逐级回退)。
   *
   * 返回 null 表示已经到根 —— 调用方据此停止回退, 否则会一路退到磁盘根。
   */
  function parentRel(rel: string): string | null {
    if (!rel) return null;
    const parts = rel.split('/').filter(Boolean);
    if (parts.length <= 1) return '';
    return parts.slice(0, -1).join('/');
  }

  /**
   * 递归列出全部文件 (仅用于"展平"模式)。
   *
   * **子目录并行遍历 (带并发上限), 顺序与串行深度优先逐字一致**: 每个目录先按名字排序收集
   * 本层文件, 再按同样的顺序拼接各子目录的结果 (`Promise.all` 保序)。
   *
   * 用 `mapLimited` 限制在 16 路: 几百个 IPC 同时打出去会淹掉 IPC 通道。并行只是让各子目录
   * 的往返不再互相等待, 顺序与内容因此都不变。
   */
  async function recursiveFiles(
    dir: string,
    baseRel: string,
    accept: (node: FileNode) => boolean,
    skip: (name: string) => boolean
  ): Promise<FileNode[]> {
    async function walk(current: string, rel: string): Promise<FileNode[]> {
      let entries: { name: string; isDirectory: boolean }[];
      try {
        entries = await fs.readDir(current);
      } catch {
        // 权限不足 / 目录消失: 跳过这一支而不是让整个展平失败
        return [];
      }
      entries.sort((left, right) => left.name.localeCompare(right.name));

      const own: FileNode[] = [];
      const subdirs: { name: string; rel: string }[] = [];
      for (const entry of entries) {
        const childRel = rel ? `${rel}/${entry.name}` : entry.name;
        if (entry.isDirectory) {
          /*
           * 展平也要遵守 `excludeTop`: 判据按**相对根的第一段**算, 这样任意深度都能命中,
           * 否则被排除目录的文件会从它的子目录里冒出来。
           */
          if (skip(entry.name)) continue;
          subdirs.push({ name: entry.name, rel: childRel });
        } else {
          const node: FileNode = {
            name: entry.name,
            path: joinNative(current, entry.name),
            rel: childRel,
            isDirectory: false,
            kind: kindFor(entry.name),
          };
          // 展平结果同样过 `includeFile`: 否则场景页展平后会混进非 .txt
          if (accept(node)) own.push(node);
        }
      }

      const nested = await mapLimited(subdirs, FLAT_WALK_CONCURRENCY, (sub) =>
        walk(joinNative(current, sub.name), sub.rel)
      );
      return nested.reduce<FileNode[]>((acc, part) => acc.concat(part), own);
    }

    return walk(dir, baseRel);
  }

  let {
    rootPath,
    onOpen,
    onDoubleClick,
    onDirectoryChange,
    selectedPath = null,
    revealRequest = null,
    onRevealComplete,
    /** 顶层不出现在列表里的目录名 (如资源浏览里隐藏 `scene`) */
    excludeTop,
    /** 由相对路径求出可预览的资源地址 */
    assetUrl,
    /** 内容变更 (新建/重命名/删除) 后递增, 强制重新加载当前目录 */
    refreshKey = 0,
    /** 可选文件过滤器 (目录始终保留) */
    includeFile,
    viewStateCache,
    viewStateKey,
    /** 工具栏右侧下拉菜单项 */
    menu,
    /** 列表项右键 (文件与文件夹都触发) */
    onItemContextMenu,
    /** 文件行右侧的附加徽标 */
    badge,
    /**
     * 列表**右侧**的附加栏 (资源浏览用它放预览)。
     *
     * 列表主体保留在 FileTree **自己**手里, 父级只提供右侧那一栏: 若改用父级 snippet 包住
     * 工具栏 + 列表, 父级任何一次重渲染都会重建整个列表 (含每行的 `<img>` 缩略图), 重新
     * 请求并解码一屏图片。
     */
    side,
    /** 列表空白处右键 */
    onBlankContextMenu,
    /** 列表空白处释放拖拽的文件/目录 */
    onDropFiles,
  }: {
    rootPath: string;
    onOpen: (file: FileNode) => void;
    onDoubleClick?: (file: FileNode) => void;
    onDirectoryChange?: (path: string) => void;
    selectedPath?: string | null;
    revealRequest?: FileTreeRevealRequest | null;
    onRevealComplete?: (id: number) => void;
    excludeTop?: (name: string) => boolean;
    assetUrl?: (rel: string) => string | undefined;
    refreshKey?: number;
    includeFile?: (node: FileNode) => boolean;
    viewStateCache?: FileTreeViewStateCache;
    viewStateKey?: string;
    menu?: (currentDir: string) => ContextMenuItem[];
    onItemContextMenu?: (node: FileNode, event: MouseEvent) => void;
    badge?: Snippet<[FileNode]>;
    side?: Snippet;
    onBlankContextMenu?: (currentDir: string, event: MouseEvent) => void;
    onDropFiles?: (currentDir: string, event: DragEvent) => void;
  } = $props();

  /*
   * 初始视图状态: **只在挂载时读一次**, 之后由组件自己的 state 接管。
   *
   * 包成 IIFE 是为了把"这里有意只取一次初值"表达清楚 —— 直接读 props 会被 Svelte 的
   * `state_referenced_locally` 规则判为可疑的"初始值捕获"。
   */
  const initial = (() => (viewStateCache && viewStateKey ? viewStateCache.get(viewStateKey) : undefined))();

  let currentRel = $state(initial?.currentRel ?? '');
  let query = $state(initial?.query ?? '');
  let flat = $state(initial?.flat ?? false);
  let visibleCount = $state(initial?.visibleCount ?? FILE_TREE_PAGE_SIZE);

  let dirEntries = $state<FileNode[]>([]);
  let flatEntries = $state<FileNode[] | null>(null);
  let searchResults = $state<FileNode[] | null>(null);
  let localRefreshKey = $state(0);
  let loadedDirectory = $state<string | null>(null);
  /** 展平/递归扫描是否还在进行 (定位要等它出结果) */
  let flatLoading = $state(false);

  let list: HTMLDivElement | undefined = $state();
  let toolbarMenuButton: HTMLButtonElement | undefined = $state();
  let toolbarMenuOpen = $state(false);
  /**
   * 面包屑下拉的坐标 (非 null 即展开)。
   *
   * 与工具栏那个"更多操作"菜单分开存: 两者可以先后打开, 共用一个状态会让先开的那个
   * 被后开的覆盖, 看起来像"点了没反应"。
   */
  let pathMenuPos = $state<{ x: number; y: number } | null>(null);
  /** 首次就绪后恢复滚动位置 (只做一次) */
  let restoredScroll = false;
  /** 上一次的目录, 用来判断"目录真的换了"而不是"被无关依赖唤醒" */
  let previousCurrentAbs: string | null = null;
  /**
   * 最近一次「定位」请求过的路径。
   *
   * 高亮用它而不是 `selectedPath`: 定位后父级会因为请求完成而清掉 `revealRequest`, 若直接
   * 依赖请求本身, 高亮会随请求一起消失。这里把"定位到了哪"记成组件内的状态。
   */
  let revealedPath = $state<string | null>(null);

  const currentAbs = $derived(currentRel ? joinNative(rootPath, currentRel.replace(/\//g, '\\')) : rootPath);

  /** 加载当前层目录。 */
  $effect(() => {
    const dir = currentAbs;
    void localRefreshKey;
    void refreshKey;

    let cancelled = false;
    void (async () => {
      try {
        const entries = await fs.readDir(dir);
        if (cancelled) return;
        const nodes = entries
          .filter((entry) => !entry.isDirectory || !excludeTop?.(entry.name))
          .map((entry) => ({
            name: entry.name,
            path: joinNative(dir, entry.name),
            rel: currentRel ? `${currentRel}/${entry.name}` : entry.name,
            isDirectory: entry.isDirectory,
            kind: entry.isDirectory ? ('other' as FileKind) : kindFor(entry.name),
          }))
          .filter((node) => node.isDirectory || !includeFile || includeFile(node))
          .sort((left, right) => {
            // 目录在前; 同类按名称 (数值感知, 让 `scene2` 排在 `scene10` 前面)
            if (left.isDirectory !== right.isDirectory) return left.isDirectory ? -1 : 1;
            // 用共享 collator: 带选项的 `localeCompare` 每次比较都要构造排序器, 11k 条目要 ~0.5s
            return compareNames(left.name, right.name);
          });
        dirEntries = nodes;
        loadedDirectory = dir;
      } catch {
        if (!cancelled) {
          dirEntries = [];
          loadedDirectory = dir;
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  });

  /** 展平模式: 递归列出当前目录下的全部文件。 */
  $effect(() => {
    const dir = currentAbs;
    const rel = currentRel;
    void localRefreshKey;
    void refreshKey;
    if (!flat) {
      flatEntries = null;
      flatLoading = false;
      return;
    }
    flatLoading = true;
    let cancelled = false;
    void (async () => {
      const files = await recursiveFiles(
        dir,
        rel,
        (node) => !includeFile || includeFile(node),
        (name) => excludeTop?.(name) ?? false
      );
      if (cancelled) return;
      flatEntries = files;
      flatLoading = false;
    })();
    return () => {
      cancelled = true;
    };
  });

  /** 搜索: 在当前已加载的条目里过滤 (不重新扫盘)。 */
  $effect(() => {
    const text = query.trim().toLowerCase();
    if (!text) {
      searchResults = null;
      return;
    }
    const source = flat ? (flatEntries ?? []) : dirEntries.filter((node) => !node.isDirectory);
    // 同时匹配名称与相对路径: 展平时用户往往记得"在哪个子目录下", 只匹配名称会搜不到
    searchResults = source.filter(
      (node) => node.name.toLowerCase().includes(text) || node.rel.toLowerCase().includes(text)
    );
  });

  /** 当前要渲染的完整列表。 */
  const allEntries = $derived<FileNode[]>(searchResults ?? (flat ? (flatEntries ?? []) : dirEntries));
  const visibleEntries = $derived(allEntries.slice(0, visibleCount));
  const hasMore = $derived(allEntries.length > visibleCount);

  /**
   * 目录或视图语义变化时把分页与滚动复位。
   *
   * **首帧必须跳过** (`previousCurrentAbs` 初值为 null): 挂载时 effect 一定会跑一次, 若那次
   * 也当成"目录变了", 就会把刚恢复出来的分页与滚动位置立刻清零 —— 于是"切走再切回"永远回到
   * 顶部。
   */
  $effect(() => {
    const dir = currentAbs;
    void query;
    void flat;
    if (previousCurrentAbs === null) {
      previousCurrentAbs = dir;
      return;
    }
    if (previousCurrentAbs === dir) return;
    previousCurrentAbs = dir;
    visibleCount = FILE_TREE_PAGE_SIZE;
    restoredScroll = false;
    if (list) list.scrollTop = 0;
  });

  /** 把视图状态写回外部缓存, 供切走再切回时恢复。 */
  $effect(() => {
    if (!viewStateCache || !viewStateKey) return;
    const scrollTop = list?.scrollTop ?? 0;
    const state: FileTreeViewState = { currentRel, query, flat, visibleCount, scrollTop };
    viewStateCache.set(viewStateKey, state);
  });

  /**
   * 定位到某个文件。
   *
   * 目标可能在子目录里, 因此先把目录切过去 (切目录会重新触发本 effect); 再扩页到能覆盖它,
   * 最后滚动到可见。完成后回调 `onRevealComplete` —— 请求是一次性的。
   *
   * **必须等对应的列表真的就绪**再动手, 否则会拿着上一份数据下结论:
   * 目录还在读、展平的递归还没结束、或搜索词刚敲下去而结果还没算完时, `allEntries` 要么是
   * 空的要么是别的目录的, `findIndex` 返回 -1, 于是定位被"成功"回调掉, 目标永远不高亮。
   */
  $effect(() => {
    const request = revealRequest;
    if (!request) return;

    // 目标在别的目录 -> 先切目录, 切完本 effect 会重跑
    const targetRel = relativeDirectoryPath(rootPath, request.path);
    if (targetRel !== null && targetRel !== currentRel) {
      currentRel = targetRel;
      query = '';
      return;
    }

    // 门禁: 三种"数据还没到"的情况一律先返回, 不下结论
    if (loadedDirectory !== currentAbs) return;
    if (flat && flatLoading) return;
    if (searchResults === null && query.trim() !== '') return;

    const index = allEntries.findIndex((node) => samePath(node.path, request.path));
    if (index >= 0 && index >= visibleCount) {
      // 目标在已渲染范围之外: 先扩页, 下一轮再滚动
      visibleCount = index + 1;
      return;
    }

    if (index >= 0 && list) {
      const row = list.querySelector<HTMLElement>(`[data-file-path="${cssEscape(request.path)}"]`);
      row?.scrollIntoView({ block: 'nearest' });
      revealedPath = request.path;
    }

    // 定位会改变滚动位置, 因此"恢复上次滚动"就此作废, 免得两个 effect 互相拉扯
    restoredScroll = true;
    onRevealComplete?.(request.id);
  });

  /** `data-file-path` 属性选择器里的路径要转义 (Windows 路径含反斜杠) */
  function cssEscape(value: string): string {
    return value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  }

  /** 首次就绪后恢复上次的滚动位置 (只恢复一次)。 */
  $effect(() => {
    if (restoredScroll || !list || !initial) return;
    if (visibleEntries.length === 0) return;
    restoredScroll = true;
    list.scrollTop = initial.scrollTop;
  });

  /**
   * 监听当前目录, 有增删改名就刷新。
   *
   * **只有展平模式才递归监听** (`watchRecursively = flat`): 分层视图只需要"这一层"的增删改名,
   * 展平视图要显示子目录里的文件, 那时才需要递归。在项目根上挂递归监听会让项目里任何活动都
   * 触发事件, 防抖后重列当前目录并重建 120 行带缩略图的行, 整个界面都会变迟钝。
   *
   * 清理函数里 unwatch: 组件卸载 / 切目录 / 切换展平时都必须撤掉, 否则每切一次就多留一个监听器。
   */
  $effect(() => {
    const dir = currentAbs;
    // 读 flat 以建立依赖: 展平开关一拨就要换一套监听
    const recursive = flat;
    let unwatch: Unwatch | null = null;
    let disposed = false;

    void (async () => {
      try {
        const stop = await fs.watchDirectory(
          dir,
          () => {
            if (!disposed) localRefreshKey += 1;
          },
          WATCH_DEBOUNCE_MS,
          recursive
        );
        // 等待期间可能已经切走或卸载了: 立刻撤掉, 不要泄漏
        if (disposed) void stop();
        else unwatch = stop;
      } catch {
        // 目录被删 / 没有监听权限: 静默降级到"只在 refreshKey 变化时刷新"
      }
    })();

    return () => {
      disposed = true;
      if (unwatch) void unwatch();
    };
  });

  /**
   * 目录消失时逐级回退到最近存在的祖先。
   *
   * 场景很常见: 在别处把当前浏览的目录删掉或改名, 文件树不该卡在一个不存在的路径上永远报
   * 空目录。回退到根还不行就停手 (不显示错误, 空目录本身就是答案)。
   */
  $effect(() => {
    const dir = currentAbs;
    void localRefreshKey;
    if (loadedDirectory !== dir) return;
    // 已经有了结果 (哪怕是空的) 且不是"读不到"的情形, 不做回退
    let cancelled = false;
    void (async () => {
      const info = await fs.exists(dir);
      if (cancelled || info.exists) return;
      const fallback = parentRel(currentRel);
      if (fallback === null) return;
      currentRel = fallback;
      query = '';
    })();
    return () => {
      cancelled = true;
    };
  });

  /** 接近底部自动补一页, 并把滚动位置写回缓存。 */
  function handleScroll(): void {
    const element = list;
    if (!element) return;

    // 滚动位置直接写缓存: `$effect` 里的那份只在响应式依赖变化时才跑, 单靠它会让
    // "滚了很远但没翻页"的位置丢失
    if (viewStateCache && viewStateKey) {
      viewStateCache.set(viewStateKey, {
        currentRel,
        query,
        flat,
        visibleCount,
        scrollTop: element.scrollTop,
      });
    }

    if (!hasMore) return;
    const remaining = element.scrollHeight - element.scrollTop - element.clientHeight;
    if (remaining > 240) return;
    visibleCount += FILE_TREE_PAGE_SIZE;
    void restoredScroll;
  }

  function openDirectory(node: FileNode): void {
    if (node.rel === currentRel) return;
    currentRel = node.rel;
    query = '';
  }

  function goUp(): void {
    const up = parentRel(currentRel);
    if (up === null) return;
    currentRel = up;
    query = '';
  }

  function goHome(): void {
    currentRel = '';
    query = '';
  }

  /**
   * 跳到某一级目录 (面包屑下拉)。
   *
   * 与"返回上一级"的区别只是目标不同, 因此共用同一条路径: 改 `currentRel` 即可,
   * 加载、视图缓存与 `onDirectoryChange` 都由监听 `currentAbs` 的那条链路接管。
   */
  function navigateTo(rel: string): void {
    // 定位高亮属于上一次定位, 手动换目录后要清掉 (否则会高亮到新目录里同名的行)
    revealedPath = null;
    currentRel = rel;
    query = '';
  }

  /** 目录真的换了就通知父级 (资源浏览用它撤销右侧预览)。 */
  $effect(() => {
    const dir = currentAbs;
    onDirectoryChange?.(dir);
  });

  /**
   * 行首的次级名称。
   *
   * 分层浏览时只显示文件名 (当前目录已经写在工具栏的面包屑里); 展平或搜索时必须显示相对
   * 路径, 否则同名文件在不同子目录下完全分不出来。
   */
  function displayRel(node: FileNode): string {
    if (!flat && !query.trim()) return node.name;
    // 相对**当前目录**而不是根: 展平的语义是"当前目录下递归", 从根算起会多出一段无关前缀
    const prefix = currentRel ? `${currentRel}/` : '';
    return node.rel.startsWith(prefix) ? node.rel.slice(prefix.length) : node.rel;
  }

  const toolbarMenuItems = $derived<ContextMenuItem[]>(menu ? menu(currentAbs) : []);
  const pathSegments = $derived(currentRel ? currentRel.split('/') : []);

  /**
   * 面包屑下拉: 从项目根到当前目录的**每一级**都能跳。
   *
   * 逐级"返回上一级"在深层目录里太慢, 所以点开就能一次跳到任意一级。第一项固定是根目录
   * (名字不叫目录名, 因为根就是资源根)。
   */
  const pathMenuItems = $derived<ContextMenuItem[]>([
    { key: 'root', label: '根目录', title: rootPath, onClick: () => navigateTo('') },
    ...pathSegments.map((segment, index) => {
      const rel = pathSegments.slice(0, index + 1).join('/');
      return { key: `directory-${index}`, label: segment, title: rel, onClick: () => navigateTo(rel) };
    }),
  ]);

  /** 在按钮下方展开面包屑 (与"更多操作"的定位方式一致, 免得两个菜单的锚点行为不同)。 */
  function openPathMenu(event: MouseEvent & { currentTarget: HTMLButtonElement }): void {
    const rect = event.currentTarget.getBoundingClientRect();
    pathMenuPos = { x: rect.left, y: rect.bottom + 4 };
  }

  /** 目录已就位但列表还没加载完时, 不把"空"当成结论。 */
  const loading = $derived(loadedDirectory !== currentAbs);
  /** 高亮: 定位优先, 其次是父级给的"当前选中" */
  const highlightPath = $derived(revealedPath ?? selectedPath);
</script>

{#snippet toolbar()}
  <div class="file-tree-toolbar">
    <button
      type="button"
      class="file-tree-icon-btn"
      title="返回根目录"
      aria-label="返回根目录"
      disabled={!currentRel}
      onclick={goHome}
    >
      <Icon name="Home" size={16} />
    </button>

    <!--
      面包屑放在工具栏**内部**: 它是"当前在哪"的提示, 与导航按钮是一组; 放在工具栏外面会多占
      一行高度, 而侧栏本来就窄。

      它**总是**显示 (根目录时显示"根目录"), 点开列出从根到当前的每一级。图标是 ChevronDown
      (它是个下拉, 不是前进)。
    -->
    <button
      type="button"
      class="file-tree-path"
      title={currentRel || '根目录'}
      aria-haspopup="menu"
      aria-expanded={pathMenuPos !== null}
      onclick={openPathMenu}
    >
      <span class="file-tree-path-label">{pathSegments.at(-1) ?? '根目录'}</span>
      <Icon name="ChevronDown" size={12} />
    </button>

    <input
      class="file-tree-search"
      placeholder={flat ? '在当前目录中递归搜索...' : '在当前目录中搜索...'}
      bind:value={query}
    />
    <button
      type="button"
      class="file-tree-flatten-btn"
      class:active={flat}
      title={flat ? '恢复分层显示' : '展平显示当前目录下的全部文件'}
      onclick={() => (flat = !flat)}
    >
      展平
    </button>
    {#if toolbarMenuItems.length > 0}
      <button
        type="button"
        class="file-tree-icon-btn"
        title="更多操作"
        aria-label="更多操作"
        bind:this={toolbarMenuButton}
        onclick={() => (toolbarMenuOpen = !toolbarMenuOpen)}
      >
        <Icon name="MoreVertical" size={16} />
      </button>
    {/if}
  </div>
{/snippet}

{#snippet listBody()}
  <div
    class="file-tree-list"
    bind:this={list}
    role="list"
    onscroll={handleScroll}
    oncontextmenu={(event) => {
      // 搜索结果是过滤视图, 在它上面新建/粘贴的目标目录不直观, 因此不给空白菜单
      if (searchResults) return;
      /*
       * 这里只管**空白处**的右键。
       *
       * 判据是"事件是不是来自某一行"(`data-file-path` 是行元素的标记) —— 结构性判据, 而不是
       * "现在有没有菜单开着": 后者会和右键菜单自己的关闭逻辑互相干扰。行的处理器已经
       * `stopPropagation()`, 这一层只是防止以后新增行类型时漏掉那一步。
       */
      const fromRow = event.target instanceof Element && event.target.closest('[data-file-path]');
      if (fromRow) return;
      event.preventDefault();
      /*
       * 菜单**只由父级提供** (`onBlankContextMenu`): 组件自己不带任何条目, 条目全部来自资源
       * 浏览 / 场景浏览。自带一份兜底菜单只会与父级给的条目不一致, 且父级漏传时才出现。
       */
      onBlankContextMenu?.(currentAbs, event);
    }}
    ondragover={(event) => {
      if (!onDropFiles) return;
      event.preventDefault();
    }}
    ondrop={(event) => {
      if (!onDropFiles) return;
      event.preventDefault();
      onDropFiles(currentAbs, event);
    }}
  >
    <!--
      返回上一级**内联在列表首行**: 它与下面的目录行是同一种动作 (进/出一层), 放进工具栏会让人
      在两个地方找同一个动作; 而且根目录时它自然消失, 不需要额外判断按钮禁用态。
    -->
    {#if currentRel && !searchResults}
      <button type="button" class="file-tree-parent" title="返回上一级目录" onclick={goUp}>
        <Icon name="ArrowUp" size={16} />
        <span>返回上一级</span>
      </button>
    {/if}

    <!--
      `flatLoading` 也要走"正在读取"这一支: 展平递归期间 `visibleEntries` 是空的, 但那是
      "还没读完"而不是"没有文件" —— 不挡住的话用户会先看到"这个目录下没有文件"这个错误结论。
      读取分支优先, 因此放在最前面。
    -->
    {#if loading || flatLoading}
      <p class="file-tree-empty muted">{loading ? '正在读取…' : '正在整理目录…'}</p>
    {:else if visibleEntries.length === 0}
      <p class="file-tree-empty muted">
        {query.trim() ? '没有匹配的文件' : flat ? '这个目录下没有文件' : '这个目录是空的'}
      </p>
    {:else}
      {#each visibleEntries as node (node.path)}
        {#if node.isDirectory}
          <div
            class="file-tree-dir"
            role="button"
            tabindex="0"
            title={node.name}
            data-file-path={node.path}
            onclick={() => openDirectory(node)}
            onkeydown={(event) => {
              if (event.key !== 'Enter' && event.key !== ' ') return;
              event.preventDefault();
              openDirectory(node);
            }}
            oncontextmenu={(event) => {
              event.preventDefault();
              /*
               * 必须阻止冒泡: 容器 `.file-tree-list` 上还有"空白处菜单"的处理器, 事件冒上去
               * 会让**两个菜单同时打开** —— 左键点遮罩只关掉其中一个, 另一个留在原地。
               */
              event.stopPropagation();
              onItemContextMenu?.(node, event);
            }}
          >
            <span class="file-tree-dir-icon"><Icon name="Folder" size={18} /></span>
            <span class="file-tree-dir-name">{middleEllipsis(node.name, 42)}</span>
            <span class="file-tree-dir-chevron"><Icon name="ChevronRight" size={14} /></span>
          </div>
        {:else}
          <button
            type="button"
            class="file-tree-file"
            class:active={highlightPath ? samePath(node.path, highlightPath) : false}
            title={node.rel}
            data-file-path={node.path}
            onclick={() => onOpen(node)}
            ondblclick={() => onDoubleClick?.(node)}
            oncontextmenu={(event) => {
              event.preventDefault();
              // 同上: 行菜单与容器上的空白菜单不能同时打开
              event.stopPropagation();
              onItemContextMenu?.(node, event);
            }}
          >
            {#if assetUrl && node.kind === 'image' && assetUrl(node.rel)}
              <!--
                **必须 `loading="lazy"`**: 列表一屏 120 行, 每行一个缩略图; 没有它会立刻把 120 张
                原图全部解码并把位图留在内存里, 进入目录、右键弹出整屏遮罩都会卡好几秒, 且离开
                资源浏览后仍然卡 (解码结果留在浏览器图片缓存里直到被淘汰)。

                `decoding="async"` 让解码不占主线程; 缩略图只给 **image** 画, 视频用 `<img>`
                只会白费一次请求与解码尝试。
              -->
              <img
                class="resource-thumb"
                src={assetUrl(node.rel)}
                alt=""
                loading="lazy"
                decoding="async"
                draggable="false"
              />
            {:else}
              <span class="resource-badge">{badgeFor(node.name, node.kind)}</span>
            {/if}
            <span class="resource-name">{middleEllipsis(displayRel(node), 40)}</span>
            {#if badge}{@render badge(node)}{/if}
          </button>
        {/if}
      {/each}

      {#if hasMore}
        <div class="file-tree-more">
          <span class="file-tree-more-count">已显示 {visibleEntries.length} / {allEntries.length}</span>
          <button type="button" class="file-tree-more-btn" onclick={() => (visibleCount += FILE_TREE_PAGE_SIZE)}>
            加载更多
          </button>
        </div>
      {/if}
    {/if}
  </div>
{/snippet}

<!--
  根容器是必须的: 父级 `.sidebar-content` 是**横向** flex, 三个平级元素 (工具栏 / 面包屑 /
  列表) 会被排成并排的三列, 文件树完全不可用。`.file-tree` 自己就是纵向 flex 列。
-->
<div class="file-tree">
  {@render toolbar()}
  {#if side}
    <!--
      "列表 + 右侧附加栏"两列。列表 (`listBody`) 与工具栏都在**本组件**里渲染, 父级只提供右侧
      那一栏 —— 这样父级重渲染不会重建列表 (见 `side` 的说明)。
    -->
    <div class="file-tree-columns">
      <div class="file-tree-main">{@render listBody()}</div>
      {@render side()}
    </div>
  {:else}
    {@render listBody()}
  {/if}
</div>

{#if pathMenuPos}
  <ContextMenu x={pathMenuPos.x} y={pathMenuPos.y} items={pathMenuItems} onClose={() => (pathMenuPos = null)} />
{/if}

{#if toolbarMenuOpen}
  <ContextMenu
    x={toolbarMenuButton?.getBoundingClientRect().left ?? 0}
    y={(toolbarMenuButton?.getBoundingClientRect().bottom ?? 0) + 4}
    items={toolbarMenuItems}
    onClose={() => (toolbarMenuOpen = false)}
  />
{/if}
